    if k=='mtime': return int(st.st_mtime)
    if k=='ctime': return int(st.st_ctime)
    lm=lst.st_mode if lst else st.st_mode; sm=st.st_mode
    if k=='is_symlink': return fi.is_symlink
    if k=='is_dir': return stat.S_ISDIR(sm)
    if k=='is_file': return stat.S_ISREG(sm)
    if k in ('is_pipe','is_fifo'): return stat.S_ISFIFO(sm)
    if k in ('is_char','is_character'): return stat.S_ISCHR(sm)
    if k=='is_block': return stat.S_ISBLK(sm)
    if k=='is_socket': return stat.S_ISSOCK(sm)
    if k=='device': return st.st_dev
    if k=='rdev': return st.st_rdev
    if k=='inode': return st.st_ino
    if k=='blocks': return getattr(st,'st_blocks',0)*2
    if k=='hardlinks': return st.st_nlink
    if k=='mode': return mode_string(lm if stat.S_ISLNK(lm) and not fi.follow else sm)
    perms=sm
