def parse_number(x):
    if isinstance(x,bool): return 1 if x else 0
    if isinstance(x,(int,float)): return x
    s=str(x).strip()
    m=re.fullmatch(r'([+-]?\d+(?:\.\d+)?)([A-Za-z]+)?', s)
    if not m: return None
    val=float(m.group(1)); unit=(m.group(2) or '').lower()
    mult={'':1,'b':1,'k':1024,'ki':1024,'kib':1024,'m':1024**2,'mi':1024**2,'mib':1024**2,'g':1024**3,'gi':1024**3,'gib':1024**3,
          't':1024**4,'ti':1024**4,'tib':1024**4,'kb':1000,'mb':1000**2,'gb':1000**3,'tb':1000**4}.get(unit)
    if mult is None: return None
    val*=mult
    return int(val) if abs(val-int(val))<1e-9 else val

def stringify(v):
    if v is None: return ''
    if isinstance(v,bool): return boolstr(v)
    if isinstance(v,float):
        if abs(v-round(v))<1e-12: return str(int(round(v)))
        return (('%f'%v).rstrip('0').rstrip('.'))
    return str(v)

class ExprParser:
    def __init__(self,tokens,fi=None,group=None): self.t=tokens; self.i=0; self.fi=fi; self.group=group
    def peek(self): return self.t[self.i] if self.i<len(self.t) else None
    def eat(self): x=self.peek(); self.i+=1; return x
    def accept(self,*vals):
        p=self.peek()
        if p and (p.low() in vals or p.v in vals) and not (p.quoted and p.v.lower() in vals): self.i+=1; return p
        return None
    def parse(self): return self.parse_or()
    def parse_or(self):
        v=self.parse_and()
        while self.accept('or'):
            v=truth(v) or truth(self.parse_and())
        return v
    def parse_and(self):
        v=self.parse_not()
        while self.accept('and'):
            v=truth(v) and truth(self.parse_not())
        return v
    def parse_not(self):
        if self.accept('not'): return not truth(self.parse_not())
        return self.parse_cmp()
    def parse_cmp(self):
        left=self.parse_add()
        p=self.peek()
        if not p: return left
        op=p.low() if not p.quoted else p.v
        cmpops={'=','==','eq','!=','<>','ne','===','eeq','!==','ene','>','gt','>=','gte','ge','<','lt','<=','lte','le','=~','~=','regexp','rx','!=~','!~=','notrx','like','notlike'}
        if op=='between':
            self.eat(); lo=self.parse_add(); self.accept('and'); hi=self.parse_add(); return compare_between(left,lo,hi)
        if op in cmpops:
            self.eat(); right=self.parse_add(); return compare(left,op,right)
        if op=='in':
            self.eat(); vals=[]
            if self.accept('(','{'):
                cur=[]; depth=0
                while self.peek() and not (depth==0 and self.peek().v in (')','}')):
                    if self.peek().v==',' and depth==0:
                        vals.append(ExprParser(cur,self.fi,self.group).parse() if cur else ''); cur=[]; self.eat(); continue
                    if self.peek().v in ('(','{'): depth+=1
                    if self.peek().v in (')','}') and depth>0: depth-=1
                    cur.append(self.eat())
                if cur: vals.append(ExprParser(cur,self.fi,self.group).parse())
                if self.peek(): self.eat()
            return any(compare(left,'===',v) or compare(left,'=',v) for v in vals)
        return left
    def parse_add(self):
        v=self.parse_mul()
        while True:
            if self.accept('+','plus'): v=num(v)+num(self.parse_mul())
            elif self.accept('-','minus'): v=num(v)-num(self.parse_mul())
            else: return v
    def parse_mul(self):
        v=self.parse_unary()
        while True:
            if self.accept('*','mul'): v=num(v)*num(self.parse_unary())
            elif self.accept('/','div'): v=num(v)/num(self.parse_unary())
            elif self.accept('%','mod'): v=num(v)%num(self.parse_unary())
            else: return v
    def parse_unary(self):
        if self.accept('-','minus'): return -num(self.parse_unary())
        return self.parse_primary()
    def parse_primary(self):
        p=self.peek()
        if not p: return ''
        if p.v in ('(','{'):
            self.eat(); v=self.parse_or();
            if self.peek() and self.peek().v in (')','}'): self.eat()
            return v
        tok=self.eat()
        if tok.quoted: return tok.v
        lw=tok.low()
        if lw in ('true','yes'): return True
        if lw in ('false','no'): return False
        if lw=='null': return ''
        # function call
        if self.peek() and self.peek().v in ('(','{'):
            openv=self.eat().v; close=')' if openv=='(' else '}'
            args=[]; cur=[]; depth=0
            while self.peek():
                if self.peek().v==close and depth==0:
                    if cur: args.append(cur)
                    self.eat(); break
                if self.peek().v==',' and depth==0:
                    args.append(cur); cur=[]; self.eat(); continue
                if self.peek().v in ('(','{'): depth+=1
                elif self.peek().v in (')','}') and depth>0: depth-=1
                cur.append(self.eat())
            vals=[ExprParser(a,self.fi,self.group).parse() for a in args]
            return eval_func(lw, vals, self.fi, self.group)
        n=parse_number(tok.v)
        if n is not None and re.match(r'^[+-]?\d', tok.v): return n
        if self.fi is not None and lw in FIELD_CANON: return field_value(lw,self.fi)
        return tok.v

def num(v):
    n=parse_number(v)
    return 0 if n is None else n

def truth(v):
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v!=0
    s=str(v).lower()
    return not (s=='' or s=='0' or s=='false' or s=='no')

def compare_between(v,lo,hi):
    nv,nlo,nhi=parse_number(v),parse_number(lo),parse_number(hi)
    if nv is not None and nlo is not None and nhi is not None: return nlo <= nv <= nhi
    sv=str(v); return str(lo) <= sv <= str(hi)

def compare(l,op,r):
    if op in ('=','==','eq','!=','<>','ne','===','eeq','!==','ene'):
        strict=op in ('===','eeq','!==','ene')
        neg=op in ('!=','<>','ne','!==','ene')
        if not strict:
            nl,nr=parse_number(l),parse_number(r)
            if nl is not None and nr is not None: res=(nl==nr)
            else:
                sl,sr=str(l),str(r)
                if any(ch in sr for ch in '*?'):
                    res=fnmatch.fnmatchcase(sl.lower(), sr.lower())
                else: res=(sl.lower()==sr.lower())
        else: res=(str(l)==str(r))
        return (not res) if neg else res
    if op in ('>','gt','>=','gte','ge','<','lt','<=','lte','le'):
        nl,nr=parse_number(l),parse_number(r)
        a,b=(nl,nr) if nl is not None and nr is not None else (str(l),str(r))
        if op in ('>','gt'): return a>b
        if op in ('>=','gte','ge'): return a>=b
        if op in ('<','lt'): return a<b
        return a<=b
    if op in ('=~','~=','regexp','rx','!=~','!~=','notrx'):
        try: res=re.search(str(r), str(l)) is not None
        except re.error: res=False
        return (not res) if op in ('!=~','!~=','notrx') else res
    if op in ('like','notlike'):
        pat=''
        for c in str(r):
            if c=='%': pat+='*'
            elif c=='_': pat+='?'
            else: pat+=c
        res=fnmatch.fnmatchcase(str(l).lower(), pat.lower())
        return not res if op=='notlike' else res
    return False

def eval_func(name, vals, fi, group):
    n=name.lower()
    if n in ('lower','lowercase','lcase'): return str(vals[0]).lower() if vals else ''
    if n in ('upper','uppercase','ucase'): return str(vals[0]).upper() if vals else ''
    if n=='initcap': return str(vals[0]).title() if vals else ''
    if n in ('length','len'): return len(str(vals[0])) if vals else 0
    if n in ('to_base64','base64'):
        return base64.b64encode(str(vals[0]).encode()).decode() if vals else ''
    if n=='from_base64':
        try: return base64.b64decode(str(vals[0])).decode()
        except Exception: return ''
    if n=='concat': return ''.join(stringify(v) for v in vals)
    if n=='concat_ws': return str(vals[0]).join(stringify(v) for v in vals[1:]) if vals else ''
    if n in ('locate','position'):
        if len(vals)<2: return 0
        pos=str(vals[0]).find(str(vals[1])); return pos+1 if pos>=0 else 0
    if n in ('substr','substring'):
        if not vals: return ''
        s=str(vals[0]); start=max(int(num(vals[1]))-1,0) if len(vals)>1 else 0
        if len(vals)>2: return s[start:start+int(num(vals[2]))]
        return s[start:]
    if n=='replace': return str(vals[0]).replace(str(vals[1]), str(vals[2])) if len(vals)>=3 else (str(vals[0]) if vals else '')
    if n=='trim': return str(vals[0]).strip() if vals else ''
    if n=='ltrim': return str(vals[0]).lstrip() if vals else ''
    if n=='rtrim': return str(vals[0]).rstrip() if vals else ''
    if n=='bin': return bin(int(num(vals[0])))[2:] if vals else ''
    if n=='hex': return format(int(num(vals[0])),'x') if vals else ''
    if n=='oct': return format(int(num(vals[0])),'o') if vals else ''
    if n=='abs': return abs(num(vals[0])) if vals else 0
    if n in ('power','pow'): return num(vals[0]) ** num(vals[1]) if len(vals)>=2 else 0
    if n=='sqrt': return math.sqrt(num(vals[0])) if vals else 0
    if n=='log': return math.log(num(vals[0]), num(vals[1])) if len(vals)>=2 else 0
    if n=='ln': return math.log(num(vals[0])) if vals else 0
    if n=='exp': return math.exp(num(vals[0])) if vals else 0
    if n=='least': return min(vals, key=lambda x: num(x) if parse_number(x) is not None else str(x)) if vals else ''
    if n=='greatest': return max(vals, key=lambda x: num(x) if parse_number(x) is not None else str(x)) if vals else ''
    if n in ('year','month','day') and vals:
        s=str(vals[0]); m=re.match(r'(\d{4})-(\d{2})-(\d{2})',s)
        if m: return int(m.group({'year':1,'month':2,'day':3}[n]))
    # Japanese/Greek predicates
    if n in ('contains_greek','greek'): return any('\u0370' <= ch <= '\u03ff' for ch in str(vals[0])) if vals else False
    if n in ('contains_japanese','japanese'): return any('\u3040' <= ch <= '\u30ff' or '\u4e00' <= ch <= '\u9fff' for ch in str(vals[0])) if vals else False
    if n in ('contains_hiragana','hiragana'): return any('\u3040' <= ch <= '\u309f' for ch in str(vals[0])) if vals else False
    if n in ('contains_katakana','katakana'): return any('\u30a0' <= ch <= '\u30ff' for ch in str(vals[0])) if vals else False
    if n in ('contains_kana','kana'): return any('\u3040' <= ch <= '\u30ff' for ch in str(vals[0])) if vals else False
    if n in ('contains_kanji','kanji'): return any('\u4e00' <= ch <= '\u9fff' for ch in str(vals[0])) if vals else False
    # Unknown function in fselect is forgiving; print name and args separately in many cases.  Return a readable fallback.
    return name

def eval_expr(tokens, fi=None, group=None):
    return ExprParser(tokens, fi, group).parse()

def is_aggregate(tokens):
    return bool(tokens and (not tokens[0].quoted) and tokens[0].low() in ('count','min','max','avg','sum') and len(tokens)>1 and tokens[1].v in ('(','{'))

def aggregate_value(tokens, files):
    name=tokens[0].low()
    # extract arg tokens inside parens
    inner=tokens[2:-1] if len(tokens)>=3 and tokens[-1].v in (')','}') else tokens[2:]
    if name=='count': return len(files)
    vals=[eval_expr(inner, fi) for fi in files]
    nums=[parse_number(v) for v in vals]
    if all(n is not None for n in nums): vals=nums
    if not vals: return '' if name in ('min','max','avg') else 0
    if name=='min': return min(vals)
    if name=='max': return max(vals)
    if name=='sum': return sum(num(v) for v in vals)
    if name=='avg': return sum(num(v) for v in vals)/len(vals)
    return ''

def label_for(tokens):
    if len(tokens)==1:
        lw=tokens[0].low()
        return FIELD_CANON.get(lw, tokens[0].v)
    if is_aggregate(tokens):
        return tokens[0].v.capitalize()
    if len(tokens)>=4 and (not tokens[0].quoted) and tokens[1].v in ('(','{'):
        inner=tokens[2:-1] if tokens[-1].v in (')','}') else tokens[2:]
        return tokens[0].v.capitalize()+"("+label_for(inner)+")"
    # arithmetic labels for common cases
    words=[]
    opnames={'+':'Add','plus':'Add','-':'Sub','minus':'Sub','*':'Mul','mul':'Mul','/':'Div','div':'Div','%':'Mod','mod':'Mod'}
    for t in tokens:
        lw=t.low()
        if lw in FIELD_CANON: words.append(FIELD_CANON[lw])
        elif lw in opnames: words.append(opnames[lw])
        elif t.v not in ('(',')','{','}',','): words.append(t.v)
    return ' '.join(words) if words else toks_to_str(tokens)

def apply_query(q, no_errors=False):
    files=[]; had_err=False
    for r in q['roots']:
        try: files.extend(traverse_root(r, no_errors))
        except RuntimeError as e:
            if not no_errors: print(str(e), file=sys.stderr)
            had_err=True
    if q['where']:
        files=[fi for fi in files if truth(eval_expr(q['where'], fi))]
    agg=any(is_aggregate(c) for c in q['columns']) or bool(q['group'])
    rows=[]; rowfiles=[]
    if agg:
        groups=OrderedDict()
        if q['group']:
            for fi in files:
                key=tuple(stringify(eval_expr(g,fi)) for g in q['group'])
                groups.setdefault(key,[]).append(fi)
        else:
            groups[('',)]=files
        for key,gfiles in groups.items():
            base=gfiles[0] if gfiles else None
            row=[]
            for c in q['columns']:
                if is_aggregate(c): row.append(aggregate_value(c,gfiles))
                else: row.append(eval_expr(c,base) if base else '')
            rows.append(row); rowfiles.append(base)
    else:
        for fi in files:
            rows.append([eval_expr(c,fi) for c in q['columns']]); rowfiles.append(fi)
    # order
    if q['order']:
        indexed=list(zip(rows,rowfiles))
        for expr,dirn in reversed(q['order']):
            def key(pair, expr=expr):
                row,fi=pair
                if len(expr)==1 and parse_number(expr[0].v) is not None:
                    idx=int(parse_number(expr[0].v))-1
                    v=row[idx] if 0<=idx<len(row) else ''
                else: v=eval_expr(expr,fi) if fi else ''
                n=parse_number(v)
                return (0,n) if n is not None else (1,str(v).lower())
            indexed.sort(key=key, reverse=(dirn=='desc'))
        rows=[p[0] for p in indexed]
    off=q['offset'] or 0
    if off: rows=rows[off:]
    if q['limit'] is not None: rows=rows[:q['limit']]
    return rows, had_err

def output_rows(rows, q):
    fmt=q['format']; labels=[label_for(c) for c in q['columns']]
    if fmt in ('tabs','tab'):
        for r in rows: print('\t'.join(stringify(v) for v in r))
    elif fmt=='lines':
        for r in rows:
            for v in r: print(stringify(v))
    elif fmt=='list':
        out=''.join(stringify(v)+'\0' for r in rows for v in r)
        sys.stdout.write(out)
    elif fmt=='csv':
        buf=io.StringIO(); w=csv.writer(buf, lineterminator='\n')
        for r in rows: w.writerow([stringify(v) for v in r])
        sys.stdout.write(buf.getvalue())
    elif fmt=='json':
        arr=[]
        for r in rows:
            d={labels[i]: stringify(r[i]) for i in range(len(labels))}
            arr.append({k:d[k] for k in sorted(d.keys())})
        sys.stdout.write(json.dumps(arr, separators=(',',':')))
    elif fmt=='html':
        title=q['query']
        s=f"<html><head><title>{html.escape(title, quote=False)}</title></head><body><table><tr><th colspan=\"{len(labels)}\">{html.escape(title, quote=False)}</th></tr>"
        for r in rows:
            s+='<tr>'+''.join(f"<td>{html.escape(stringify(v), quote=False)}</td>" for v in r)+'</tr>'
        s+='</table></body></html>'
        sys.stdout.write(s)
    else:
        for r in rows: print('\t'.join(stringify(v) for v in r))

def run_query(qs, no_errors=False):
    q=parse_query(qs)
    rows, had_err=apply_query(q, no_errors)
    output_rows(rows,q)
    return 1 if had_err else 0

def interactive(no_errors=False):
    errors=not no_errors
    while True:
        try:
            if sys.stdin.isatty(): sys.stdout.write('> '); sys.stdout.flush()
            line=sys.stdin.readline()
            if line=='': break
            line=line.rstrip('\n')
        except KeyboardInterrupt: break
        if not line: continue
        low=line.strip().lower()
        if low in ('quit','exit'): break
        if low=='pwd': print(os.getcwd()); continue
        if low.startswith('cd '):
            try: os.chdir(os.path.expanduser(line.strip()[3:].strip()))
            except OSError as e:
                if errors: print(f"{e.strerror} (os error {e.errno})", file=sys.stderr)
            continue
        if low=='errors off': errors=False; print('Errors are OFF'); continue
        if low=='errors on': errors=True; print('Errors are ON'); continue
        try: run_query(line, no_errors=not errors)
        except Exception as e:
            if errors: print(str(e) if str(e).startswith('query:') else f"query: {e}", file=sys.stderr)
    return 0

def main(argv):
    if not argv:
        sys.stdout.write(banner(False)); return 0
    # observed: help is recognized when it is the first argument; color disabling does not affect help banner.
    if argv[0] in ('--help','-h','/?','/h'):
        sys.stdout.write(banner(True)); return 0
    no_errors=False; interactive_mode=False; qargs=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a in ('--interactive','-i','/i'): interactive_mode=True; i+=1; continue
        if a in ('--no-errors',): no_errors=True; i+=1; continue
        if a in ('--nocolor','--no-color','/nocolor'): i+=1; continue
        if a in ('--config','-c','/config') and i+1<len(argv): i+=2; continue
        qargs.extend(argv[i:]); break
    if interactive_mode: return interactive(no_errors)
    if not qargs:
        sys.stdout.write(banner(False)); return 0
    qs=' '.join(qargs)
    try:
        return run_query(qs, no_errors)
    except ValueError as e:
        if not no_errors: print(str(e), file=sys.stderr)
        return 2
    except Exception as e:
        if not no_errors: print(f"query: {e}", file=sys.stderr)
        return 2

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
