class Token:
    __slots__ = ('v','quoted')
    def __init__(self, v, quoted=False): self.v=v; self.quoted=quoted
    def low(self): return self.v.lower()
    def __repr__(self): return f"T({self.v!r},{self.quoted})"

def tokenize(s):
    out=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isspace(): i+=1; continue
        if c in "'\"`":
            q=c; i+=1; buf=[]
            while i<n:
                if s[i]=='\\' and i+1<n:
                    buf.append(s[i+1]); i+=2; continue
                if s[i]==q:
                    i+=1; break
                buf.append(s[i]); i+=1
            out.append(Token(''.join(buf), True)); continue
        if c in ',(){}':
            out.append(Token(c)); i+=1; continue
        # multi-character operators
        for op in ('!==','===','!=~','!~=','>=','<=','!=','<>','==','=~','~='):
            if s.startswith(op,i): out.append(Token(op)); i+=len(op); break
        else:
            if c in '<>=':
                out.append(Token(c)); i+=1; continue
            if c in '+%':
                out.append(Token(c)); i+=1; continue
            if c=='*':
                # glob at beginning, operator otherwise
                if i+1<n and (s[i+1] not in ' \t\r\n,(){}') and (not out or out[-1].v in '(),{}' or out[-1].low() in {'=','==','!=','like','notlike'}):
                    j=i+1
                    while j<n and (not s[j].isspace()) and s[j] not in ',(){}<>=!~+%': j+=1
                    out.append(Token(s[i:j])); i=j
                else:
                    out.append(Token('*')); i+=1
                continue
            if c=='-' and i+1<n and s[i+1].isdigit():
                j=i+2
                while j<n and (s[j].isalnum() or s[j] in '._') : j+=1
                out.append(Token(s[i:j])); i=j; continue
            if c=='-' and (i+1>=n or not s[i+1].isspace()):
                # part of a bare word/path/date unless surrounded by spaces
                pass
            # bare word; stop on operators and punctuation, but keep slash and hyphen for paths/dates
            j=i
            while j<n and (not s[j].isspace()) and s[j] not in ',(){}<>=!~+%':
                if s[j]=='*' and j>i: break
                j+=1
            if j==i:
                out.append(Token(c)); i+=1
            else:
                out.append(Token(s[i:j])); i=j
    return out

def normkw(t): return t.low() if isinstance(t,Token) else str(t).lower()
def is_kw(t, w): return isinstance(t,Token) and (not t.quoted) and t.low()==w

def find_section(tokens, start=0):
    pos={}; depth=0; i=start
    while i<len(tokens):
        v=tokens[i].v
        if v in ('(','{'): depth+=1
        elif v in (')','}') and depth>0: depth-=1
        if depth==0 and not tokens[i].quoted:
            lw=tokens[i].low()
            if lw in ('from','where','limit','offset','into') and lw not in pos: pos[lw]=i
            if lw=='group' and i+1<len(tokens) and is_kw(tokens[i+1],'by') and 'group' not in pos: pos['group']=i
            if lw=='order' and i+1<len(tokens) and is_kw(tokens[i+1],'by') and 'order' not in pos: pos['order']=i
        i+=1
    return pos

def split_top(tokens, sep=','):
    res=[]; cur=[]; depth=0
    for t in tokens:
        if t.v in ('(','{'): depth+=1
        elif t.v in (')','}') and depth>0: depth-=1
        if depth==0 and t.v==sep:
            res.append(cur); cur=[]
        else: cur.append(t)
    res.append(cur)
    return [r for r in res if r]

def split_columns(tokens):
    if any(t.v==',' for t in tokens): return split_top(tokens, ',')
    # If no commas, fselect accepts whitespace-separated simple columns.  Keep expressions/functions together.
    res=[]; i=0
    while i<len(tokens):
        if i+1<len(tokens) and tokens[i+1].v in ('(','{'):
            cur=[tokens[i],tokens[i+1]]; depth=1; i+=2
            while i<len(tokens) and depth:
                cur.append(tokens[i])
                if tokens[i].v in ('(','{'): depth+=1
                elif tokens[i].v in (')','}'): depth-=1
                i+=1
            res.append(cur)
        else:
            res.append([tokens[i]]); i+=1
    return [r for r in res if r]

def toks_to_str(ts):
    parts=[]
    for t in ts:
        if t.v in (')','}',',') and parts: parts[-1]+=t.v
        elif t.v in ('(','{') and parts: parts[-1]+=t.v
        else: parts.append(t.v)
    return ' '.join(parts)

def parse_query(q):
    toks=tokenize(q)
    if not toks: raise ValueError('query: Error parsing expression, expecting string')
    if is_kw(toks[0],'select'): toks=toks[1:]
    sec=find_section(toks)
    starts=[v for v in sec.values()]
    col_end=min(starts) if starts else len(toks)
    cols=split_columns(toks[:col_end])
    if not cols: raise ValueError('query: Error parsing expression, expecting string')
    def next_after(name, default=len(toks)):
        if name not in sec: return None
        p=sec[name]; candidates=[v for k,v in sec.items() if v>p]
        return min(candidates) if candidates else len(toks)
    roots=[]
    if 'from' in sec:
        roots=parse_roots(toks[sec['from']+1:next_after('from')])
    else:
        roots=[{'path':'.','mindepth':0,'maxdepth':None,'symlinks':False,'dfs':False}]
    where=toks[sec['where']+1:next_after('where')] if 'where' in sec else []
    if 'where' in sec and not where: raise ValueError('query: Error parsing expression, expecting string')
    group=split_top(toks[sec['group']+2:next_after('group')], ',') if 'group' in sec else []
    order=parse_order(toks[sec['order']+2:next_after('order')]) if 'order' in sec else []
    limit=None; offset=0; fmt='tabs'
    if 'limit' in sec:
        a=toks[sec['limit']+1:next_after('limit')]
        if a: limit=int(float(a[0].v))
    if 'offset' in sec:
        a=toks[sec['offset']+1:next_after('offset')]
        if a: offset=int(float(a[0].v))
    if 'into' in sec:
        a=toks[sec['into']+1:next_after('into')]
        if a: fmt=a[0].low()
    return {'columns':cols,'roots':roots,'where':where,'group':group,'order':order,'limit':limit,'offset':offset,'format':fmt,'query':q}

def parse_roots(tokens):
    groups=split_top(tokens, ',') if tokens else []
    roots=[]
    opts={'mindepth','maxdepth','depth','symlinks','sym','archives','arc','gitignore','git','nogitignore','nogit','hgignore','hg','dockerignore','docker','dfs','bfs','regexp','rx','as'}
    for g in groups:
        if not g: continue
        r={'path':None,'mindepth':0,'maxdepth':None,'symlinks':False,'dfs':False,'archives':False}
        i=0
        if i<len(g): r['path']=g[i].v; i+=1
        while i<len(g):
            lw=g[i].low()
            if lw in ('mindepth','maxdepth','depth'):
                if i+1<len(g):
                    try: val=int(float(g[i+1].v))
                    except Exception: val=0
                    if lw=='mindepth': r['mindepth']=val
                    else: r['maxdepth']=val
                    i+=2; continue
            elif lw in ('symlinks','sym'): r['symlinks']=True
            elif lw in ('archives','arc'): r['archives']=True
            elif lw=='dfs': r['dfs']=True
            elif lw=='bfs': r['dfs']=False
            elif lw=='as': i+=2; continue
            i+=1
        if r['path']: roots.append(r)
    return roots or [{'path':'.','mindepth':0,'maxdepth':None,'symlinks':False,'dfs':False}]

def parse_order(tokens):
    res=[]
    for g in split_top(tokens, ','):
        if not g: continue
        direction='asc'
        if (not g[-1].quoted) and g[-1].low() in ('asc','desc'):
            direction=g[-1].low(); g=g[:-1]
        if g: res.append((g,direction))
    return res

class FileInfo:
    __slots__=('root','full','rel','name','follow','lst','st','err')
    def __init__(self, root, full, rel, follow=False):
        self.root=root; self.full=full; self.rel=rel.replace(os.sep,'/') or os.path.basename(full); self.name=os.path.basename(full); self.follow=follow; self.err=None
        try: self.lst=os.lstat(full)
        except OSError as e: self.lst=None; self.st=None; self.err=e; return
        try: self.st=os.stat(full) if follow else self.lst
        except OSError: self.st=self.lst
    @property
    def ext(self):
        n=self.name
        if n.startswith('.') and n.count('.')==1: return ''
        e=os.path.splitext(n)[1]
        return e[1:] if e.startswith('.') else e
    @property
    def filename(self):
        n=self.name
        if n.startswith('.') and n.count('.')==1: return n
        return os.path.splitext(n)[0]
    @property
    def is_symlink(self): return self.lst is not None and stat.S_ISLNK(self.lst.st_mode)
    def mode_for_type(self): return self.lst.st_mode if self.lst is not None else 0
    def mode_for_perm(self): return self.st.st_mode if self.st is not None else 0

def canonical_root(p):
    p=os.path.expanduser(p)
    try: rp=os.path.realpath(p)
    except Exception: rp=os.path.abspath(p)
    if not os.path.exists(rp): raise OSError(2, 'No such file or directory')
    if not os.path.isdir(rp): raise OSError(20, 'Not a directory')
    return rp

def traverse_root(r, no_errors=False):
    root_arg=r['path']
    try: root=canonical_root(root_arg)
    except OSError as e:
        raise RuntimeError(f"{root_arg}: could not canonicalize path: {e.strerror} (os error {e.errno})" if e.errno==2 else f"{root_arg}: {e.strerror} (os error {e.errno})")
    follow=r.get('symlinks',False); maxd=r.get('maxdepth'); mind=r.get('mindepth',0)
    items=[]
    if r.get('dfs'):
        stack=[(root,'',1)]
        while stack:
            d, relbase, depth=stack.pop()
            try: entries=list(os.scandir(d))
            except OSError as e:
                if not no_errors: print(f"{d}: {e.strerror} (os error {e.errno})", file=sys.stderr)
                continue
            # approximate depth-first while keeping directory listing order
            pending=[]
            for ent in entries:
                rel=(relbase+'/'+ent.name).strip('/')
                fi=FileInfo(root, ent.path, rel, follow)
                if depth>=mind: items.append(fi)
                if fi.lst and stat.S_ISDIR(fi.lst.st_mode) and not stat.S_ISLNK(fi.lst.st_mode) and (maxd is None or depth<maxd):
                    pending.append((ent.path, rel, depth+1))
            stack.extend(reversed(pending))
    else:
        q=deque([(root,'',1)])
        while q:
            d, relbase, depth=q.popleft()
            try: entries=list(os.scandir(d))
            except OSError as e:
                if not no_errors: print(f"{d}: {e.strerror} (os error {e.errno})", file=sys.stderr)
                continue
            for ent in entries:
                rel=(relbase+'/'+ent.name).strip('/')
                fi=FileInfo(root, ent.path, rel, follow)
                if depth>=mind: items.append(fi)
                if fi.lst and stat.S_ISDIR(fi.lst.st_mode) and not stat.S_ISLNK(fi.lst.st_mode) and (maxd is None or depth<maxd):
                    q.append((ent.path, rel, depth+1))
    return items

def boolstr(b): return 'true' if bool(b) else 'false'
def timestr(ts): return time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(ts))
def human_size(n):
    try: n=int(n)
    except Exception: return ''
    units=['B','KiB','MiB','GiB','TiB','PiB']; val=float(n); idx=0
    while abs(val)>=1024 and idx<len(units)-1:
        val/=1024.0; idx+=1
    if idx==0: return f"{n}B"
    if abs(val-round(val))<1e-9: return f"{int(round(val))}{units[idx]}"
    return f"{val:.2f}{units[idx]}"

def mode_string(mode):
    ft='?'
    if stat.S_ISREG(mode): ft='-'
    elif stat.S_ISDIR(mode): ft='d'
    elif stat.S_ISLNK(mode): ft='l'
    elif stat.S_ISFIFO(mode): ft='p'
    elif stat.S_ISCHR(mode): ft='c'
    elif stat.S_ISBLK(mode): ft='b'
    elif stat.S_ISSOCK(mode): ft='s'
    s=[ft]
    bits=[stat.S_IRUSR,stat.S_IWUSR,stat.S_IXUSR,stat.S_IRGRP,stat.S_IWGRP,stat.S_IXGRP,stat.S_IROTH,stat.S_IWOTH,stat.S_IXOTH]
    chars='rwxrwxrwx'
    for bit,ch in zip(bits,chars): s.append(ch if mode & bit else '-')
    if mode & stat.S_ISUID: s[3]='s' if mode & stat.S_IXUSR else 'S'
    if mode & stat.S_ISGID: s[6]='s' if mode & stat.S_IXGRP else 'S'
    if mode & stat.S_ISVTX: s[9]='t' if mode & stat.S_IXOTH else 'T'
    return ''.join(s)

def file_bytes(path, limit=None):
    try:
        with open(path,'rb') as f: return f.read() if limit is None else f.read(limit)
    except Exception: return None

def file_hash(path, kind):
    try:
        h = hashlib.sha1() if kind=='sha1' else hashlib.sha256() if kind=='sha256' else hashlib.sha512() if kind=='sha512' else hashlib.sha3_512()
        with open(path,'rb') as f:
            for b in iter(lambda:f.read(65536), b''): h.update(b)
        return h.hexdigest()
    except Exception: return ''

def image_dim(fi):
    data=file_bytes(fi.full, 64)
    if not data: return (None,None)
    try:
        if data.startswith(b'\x89PNG\r\n\x1a\n') and len(data)>=24:
            return (int.from_bytes(data[16:20],'big'), int.from_bytes(data[20:24],'big'))
        if data[:6] in (b'GIF87a',b'GIF89a') and len(data)>=10:
            return (int.from_bytes(data[6:8],'little'), int.from_bytes(data[8:10],'little'))
    except Exception: pass
    return (None,None)

def field_value(name, fi):
    k=name.lower()
    st=fi.st; lst=fi.lst
    if st is None: return ''
    if k=='name': return fi.name
    if k in ('filename','fname'): return fi.filename
    if k in ('extension','ext'): return fi.ext
    if k=='path': return fi.rel
    if k=='abspath': return os.path.realpath(fi.full)
    if k in ('directory','dirname','dir'):
        d=os.path.dirname(fi.rel); return '' if d=='.' else d
    if k=='absdir': return os.path.dirname(os.path.realpath(fi.full))
    if k=='size': return st.st_size
    if k in ('fsize','hsize'): return human_size(st.st_size)
    if k=='uid': return st.st_uid
    if k=='gid': return st.st_gid
    if k=='user':
        try: return pwd.getpwuid(st.st_uid).pw_name
        except KeyError: return st.st_uid
    if k=='group':
        try: return grp.getgrgid(st.st_gid).gr_name
        except KeyError: return st.st_gid
    if k=='created': return timestr(getattr(st,'st_birthtime',st.st_ctime))
    if k=='accessed': return timestr(st.st_atime)
    if k=='modified': return timestr(st.st_mtime)
    if k=='atime': return int(st.st_atime)
    if k=='mtime': return int(st.st_mtime)
    if k=='ctime': return int(st.st_ctime)
