        files=[fi for fi in files if truth(eval_expr(q['where'], fi))]
    agg=any(is_aggregate(c) for c in q['columns']) or bool(q['group'])
    rows=[]; rowfiles=[]
    if agg:
        groups=OrderedDict()
        if q['group']:
            for fi in files:
                key=tuple(stringify(eval_expr(g,fi)) for g in q['group'])
                groups.setdefault(key,[]).append(fi)
        else:
            groups[('',)]=files
        for key,gfiles in groups.items():
            base=gfiles[0] if gfiles else None
            row=[]
            for c in q['columns']:
                if is_aggregate(c): row.append(aggregate_value(c,gfiles))
                else: row.append(eval_expr(c,base) if base else '')
            rows.append(row); rowfiles.append(base)
