    if q['order']:
        indexed=list(zip(rows,rowfiles))
        for expr,dirn in reversed(q['order']):
            def key(pair, expr=expr):
                row,fi=pair
                if len(expr)==1 and parse_number(expr[0].v) is not None:
                    idx=int(parse_number(expr[0].v))-1
                    v=row[idx] if 0<=idx<len(row) else ''
                else: v=eval_expr(expr,fi) if fi else ''
                n=parse_number(v)
