        for r in rows: print('\t'.join(stringify(v) for v in r))
    elif fmt=='lines':
        for r in rows:
            for v in r: print(stringify(v))
    elif fmt=='list':
        out=''.join(stringify(v)+'\0' for r in rows for v in r)
        sys.stdout.write(out)
    elif fmt=='csv':
        buf=io.StringIO(); w=csv.writer(buf, lineterminator='\n')
        for r in rows: w.writerow([stringify(v) for v in r])
        sys.stdout.write(buf.getvalue())
    elif fmt=='json':
        arr=[]
        for r in rows:
            d={labels[i]: stringify(r[i]) for i in range(len(labels))}
            arr.append({k:d[k] for k in sorted(d.keys())})
